-- Site Pack Database Sources
-- This table defines the *sources* themselves (e.g., the URL to a site pack).
CREATE TABLE IF NOT EXISTS site_packs (
    -- UUIDv7 if generated by the engine
    -- a normal string otherwise
    id TEXT NOT NULL PRIMARY KEY,

    -- local if NULL, remote otherwise
    remote_id TEXT,

    name TEXT NOT NULL,

    description TEXT,

    requires_pro BOOLEAN NOT NULL DEFAULT TRUE,
    last_updated_at TEXT,
    version TEXT,
    is_ignored BOOLEAN NOT NULL DEFAULT FALSE,
    icon TEXT
);
